CREATE OR REPLACE FUNCTION public.infra_authorize_action(p_config_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.infra_monitor_configs;
BEGIN
  SELECT * INTO c FROM public.infra_monitor_configs WHERE id=p_config_id;
  IF NOT FOUND OR NOT public.infra_is_developer(c.store_id) THEN RAISE EXCEPTION 'infra_forbidden' USING ERRCODE='42501'; END IF;
  IF p_action NOT IN ('test_connection','collect') THEN RAISE EXCEPTION 'infra_invalid_action'; END IF;
  INSERT INTO public.infra_config_audit(config_id,actor_id,action,config_version) VALUES(c.id,auth.uid(),p_action,c.version);
END;
$function$

CREATE OR REPLACE FUNCTION public.infra_save_config(p_config_id uuid, p_expected_version integer, p_config jsonb, p_limits jsonb)
 RETURNS infra_monitor_configs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE before_row public.infra_monitor_configs; after_row public.infra_monitor_configs; item jsonb; limits_before jsonb;
BEGIN
  SELECT * INTO before_row FROM public.infra_monitor_configs WHERE id=p_config_id FOR UPDATE;
  IF NOT FOUND OR NOT public.infra_is_developer(before_row.store_id) THEN
    RAISE EXCEPTION 'infra_forbidden' USING ERRCODE='42501';
  END IF;
  IF before_row.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'infra_version_conflict' USING ERRCODE='40001'; END IF;
  IF jsonb_typeof(p_config) IS DISTINCT FROM 'object' OR p_config IS NULL
    OR (p_config-ARRAY['enabled','mode','project_ref','account_scope_id','plan_label','refresh_minutes','retention_days','alert_thresholds_json'])<>'{}'
    OR NOT (p_config ?& ARRAY['enabled','mode','project_ref','account_scope_id','plan_label','refresh_minutes','retention_days','alert_thresholds_json'])
    OR jsonb_typeof(p_config->'enabled') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(p_config->'mode') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_config->'plan_label') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_config->'refresh_minutes') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_config->'retention_days') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_config->'project_ref') NOT IN ('string','null')
    OR jsonb_typeof(p_config->'account_scope_id') NOT IN ('string','null')
    OR jsonb_typeof(p_config->'alert_thresholds_json') IS DISTINCT FROM 'object'
    OR ((p_config->'alert_thresholds_json')-ARRAY['warning','critical'])<>'{}'
    OR jsonb_typeof(p_limits) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'infra_invalid_config'; END IF;
  IF jsonb_array_length(p_limits)>30 THEN RAISE EXCEPTION 'infra_invalid_limits'; END IF;
  UPDATE public.infra_monitor_configs SET enabled=(p_config->>'enabled')::boolean,mode=p_config->>'mode',
    project_ref=p_config->>'project_ref',account_scope_id=p_config->>'account_scope_id',plan_label=p_config->>'plan_label',
    refresh_minutes=(p_config->>'refresh_minutes')::integer,retention_days=(p_config->>'retention_days')::integer,
    alert_thresholds_json=p_config->'alert_thresholds_json',version=version+1,updated_at=now(),updated_by=auth.uid()
    WHERE id=p_config_id RETURNING * INTO after_row;
  SELECT coalesce(jsonb_agg(to_jsonb(l)),'[]'::jsonb) INTO limits_before FROM public.infra_metric_limits l WHERE l.config_id=p_config_id;
  DELETE FROM public.infra_metric_limits WHERE config_id=p_config_id;
  FOR item IN SELECT value FROM jsonb_array_elements(p_limits) LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object'
      OR (item-ARRAY['metric_key','unit','quota_scope','scope_id','period_type','period_start','period_end','max_value','source','effective_at'])<>'{}'
      OR NOT(item ?& ARRAY['metric_key','unit','quota_scope','scope_id','period_type','period_start','period_end','max_value','source','effective_at'])
      OR jsonb_typeof(item->'max_value') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'infra_invalid_limit'; END IF;
    INSERT INTO public.infra_metric_limits(config_id,metric_key,unit,quota_scope,scope_id,period_type,period_start,period_end,max_value,source,effective_at)
    VALUES(p_config_id,item->>'metric_key',item->>'unit',item->>'quota_scope',item->>'scope_id',item->>'period_type',
      (item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz,(item->>'max_value')::numeric,
      item->>'source',(item->>'effective_at')::timestamptz);
  END LOOP;
  INSERT INTO public.infra_config_audit(config_id,actor_id,action,config_version,details)
    VALUES(p_config_id,auth.uid(),'save',after_row.version,
      jsonb_build_object('before',to_jsonb(before_row),'after',to_jsonb(after_row),'limits_before',limits_before,'limits_after',p_limits));
  RETURN after_row;
END;
$function$
